using System.ComponentModel;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration -----------------------------------------------------------

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running this app.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Chat client -------------------------------------------------------------

IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Tools -------------------------------------------------------------------

var notebook = new Notebook();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        (string query) => WebSearch.SearchAsync(query),
        nameof(WebSearch.SearchAsync),
        "Searches the web for the given query and returns a list of result snippets. " +
        "Use this to find information about a research topic."),

    AIFunctionFactory.Create(
        ([Description("A concise key or title for the note")] string key,
         [Description("The content to save")] string content) =>
        {
            notebook.Save(key, content);
            return $"Note saved under '{key}'.";
        },
        "SaveNote",
        "Saves a research note. Use this to record important findings during research."),

    AIFunctionFactory.Create(
        () => notebook.GetAll(),
        "GetNotes",
        "Returns all previously saved research notes as a dictionary of key-value pairs."),
};

// --- Agent setup -------------------------------------------------------------

var agent = new ChatClientAgent(
    chatClient,
    instructions:
        """
        You are a research agent. Your job is to thoroughly research a topic
        provided by the user and produce a well-organized summary.

        Follow this workflow:
        1. Break the topic into 2-3 search queries that cover different angles.
        2. Use the web search tool for each query.
        3. Save important findings using the SaveNote tool.
        4. After gathering enough information, retrieve your notes with GetNotes.
        5. Synthesize everything into a clear, structured summary with sections
           and bullet points. Cite the sources where possible.

        Be thorough but concise. Do not fabricate information — only report
        what the search results contain.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics using web search and note-taking tools.",
    tools: tools);

// --- Run ---------------------------------------------------------------------

Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        🔍  Research Agent  🔍           ║");
Console.WriteLine("╠══════════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research, or 'quit'.  ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    Console.WriteLine();
    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("Researching… (this may take a moment)");
    Console.ResetColor();

    var runOptions = new ChatClientAgentRunOptions
    {
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 4096,
        },
    };

    try
    {
        var session = await agent.CreateSessionAsync();

        await foreach (var update in agent.RunStreamingAsync(
            $"Research the following topic and provide a comprehensive summary:\n\n{topic}",
            session,
            runOptions))
        {
            if (update.Role == ChatRole.Assistant && update.Text is { Length: > 0 } text)
            {
                Console.Write(text);
            }
        }

        Console.WriteLine();
        Console.WriteLine();
    }
    catch (Exception ex)
    {
        Console.ForegroundColor = ConsoleColor.Red;
        Console.WriteLine($"Error: {ex.Message}");
        Console.ResetColor();
    }

    notebook.Clear();
}

Console.WriteLine("Goodbye!");

// --- Supporting types --------------------------------------------------------

/// <summary>
/// Web search using the DuckDuckGo Instant Answer API (no key required).
/// Replace with Bing, Google, or Tavily for production use.
/// </summary>
static class WebSearch
{
    private static readonly HttpClient Http = new();

    public static async Task<string> SearchAsync(string query)
    {
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await Http.GetStringAsync(url);
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<string>();

            if (root.TryGetProperty("Abstract", out var abs) && abs.GetString() is { Length: > 0 } abstract_)
            {
                var source = root.TryGetProperty("AbstractURL", out var aurl) ? aurl.GetString() : "";
                results.Add($"[Summary] {abstract_} (source: {source})");
            }

            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } t)
                    {
                        var firstUrl = topic.TryGetProperty("FirstURL", out var fu) ? fu.GetString() : "";
                        results.Add($"[Related] {t} (source: {firstUrl})");
                    }
                }
            }

            if (results.Count > 0)
                return string.Join("\n\n", results);

            return $"No detailed results found for '{query}'. Try rephrasing the search query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }
}

/// <summary>
/// Simple in-memory notebook for storing research notes between tool calls.
/// </summary>
sealed class Notebook
{
    private readonly Dictionary<string, string> _notes = new();

    public void Save(string key, string content) => _notes[key] = content;

    public Dictionary<string, string> GetAll() => new(_notes);

    public void Clear() => _notes.Clear();
}

