/// <summary>
/// Simulated web search that returns plausible snippets.
/// Replace with a real search API (Bing, Google, Tavily, etc.) for production use.
/// </summary>
static class WebSearch
{
    private static readonly HttpClient Http = new();

    public static async Task<string> SearchAsync(string query)
    {
        // Try DuckDuckGo Instant Answer API (no key required, returns JSON).
        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
            var json = await Http.GetStringAsync(url);
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var results = new List<string>();

            if (root.TryGetProperty("Abstract", out var abs) && abs.GetString() is { Length: > 0 } abstract_)
            {
                var source = root.TryGetProperty("AbstractURL", out var aurl) ? aurl.GetString() : "";
                results.Add($"[Summary] {abstract_} (source: {source})");
            }

            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var topic in topics.EnumerateArray().Take(5))
                {
                    if (topic.TryGetProperty("Text", out var text) && text.GetString() is { Length: > 0 } t)
                    {
                        var firstUrl = topic.TryGetProperty("FirstURL", out var fu) ? fu.GetString() : "";
                        results.Add($"[Related] {t} (source: {firstUrl})");
                    }
                }
            }

            if (results.Count > 0)
                return string.Join("\n\n", results);

            return $"No detailed results found for '{query}'. Try rephrasing the search query.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }
}

/// <summary>
