sealed class Notebook
{
    private readonly Dictionary<string, string> _notes = new();

    public void Save(string key, string content) => _notes[key] = content;

    public Dictionary<string, string> GetAll() => new(_notes);

    public void Clear() => _notes.Clear();
}

